use ycoding_core::regexp::{Budget, Match, RegExp};
#[test]
fn native_boundary_0() {
    {
        let regex = RegExp::new(&[0u16; 0], "").unwrap();
        assert_eq!(regex.source(), &[40, 63, 58, 41]);
        assert_eq!(regex.flags(), "");
    }
}
#[test]
fn native_boundary_1() {
    {
        let mut regex = RegExp::new(&[40, 63, 58, 41], "").unwrap();
        regex.last_index = 0;
        let mut budget = Budget::unlimited();
        assert_eq!(
            regex.exec(&[0u16; 0], &mut budget).unwrap(),
            Some(Match {
                captures: vec![Some([0u16; 0].to_vec())],
                index: 0,
                groups: None,
                indices: None,
                index_groups: None
            })
        );
        assert_eq!(regex.last_index, 0);
    }
}
